function StatusTag({ status, styles }) {
  const s = styles[status] || styles[Object.keys(styles)[0]];
  return (
    <span className={`inline-flex items-center gap-1.5 font-mono text-xs tracking-wider ${s.text}`}>
      <span className={`h-1.5 w-1.5 rounded-full ${s.dot}`} />
      {s.label}
    </span>
  );
}

function renderDescription(description, t) {
  if (typeof description === "string") return description;
  return description.map((part, i) =>
    typeof part === "string" ? (
      <React.Fragment key={i}>{part}</React.Fragment>
    ) : (
      <span key={i} className={`${t.accent} font-medium`}>
        {part.hl}
      </span>
    )
  );
}

function SectionHeading({ eyebrow, title, subtitle, t }) {
  return (
    <div className="mb-10 sm:mb-14">
      <p className={`font-mono text-xs tracking-widest ${t.accent} mb-3`}>{eyebrow}</p>
      <h2 className={`font-display text-2xl sm:text-3xl font-semibold ${t.text} mb-2`}>{title}</h2>
      {subtitle && <p className={`font-body text-sm ${t.textMuted} max-w-xl`}>{subtitle}</p>}
    </div>
  );
}

/* ============================================================
   GitHub contribution activity (real data via a public,
   no-auth, CORS-enabled API that reads a user's public
   contribution graph: github-contributions-api.jogruber.de)
   ============================================================ */
const DOT_RADIUS_BY_LEVEL = [1.4, 2.2, 3, 3.8, 4.6];

function GithubActivity({ t, isDark }) {
  const [status, setStatus] = useState("loading"); // loading | ready | error
  const [weeks, setWeeks] = useState([]);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    let cancelled = false;
    fetch(`https://github-contributions-api.jogruber.de/v4/${PROFILE.githubUsername}?y=last`)
      .then((res) => {
        if (!res.ok) throw new Error("Request failed");
        return res.json();
      })
      .then((json) => {
        if (cancelled || !json || !Array.isArray(json.contributions)) throw new Error("Bad payload");
        const days = json.contributions;
        const sum = days.reduce((acc, d) => acc + (d.count || 0), 0);

        // Group into weeks (columns), Sunday-first rows, matching GitHub's own layout.
        const cols = [];
        let currentWeek = new Array(7).fill(null);
        days.forEach((day) => {
          const dow = new Date(day.date + "T00:00:00").getDay();
          currentWeek[dow] = day;
          if (dow === 6) {
            cols.push(currentWeek);
            currentWeek = new Array(7).fill(null);
          }
        });
        if (currentWeek.some((d) => d !== null)) cols.push(currentWeek);

        if (!cancelled) {
          setWeeks(cols);
          setTotal(sum);
          setStatus("ready");
        }
      })
      .catch(() => {
        if (!cancelled) setStatus("error");
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const dotColor = isDark ? "#e2e8f0" : "#1e293b";
  const cellSize = 12;
  const width = weeks.length * cellSize;
  const height = 7 * cellSize;

  return (
    <section id="github-activity" className="max-w-6xl mx-auto px-5 sm:px-8 py-24">
      <div className="flex items-end justify-between flex-wrap gap-3 mb-10 sm:mb-14">
        <div>
          <p className={`font-mono text-xs tracking-widest ${t.accent} mb-3`}>06 · GITHUB</p>
          <h2 className={`font-display text-2xl sm:text-3xl font-semibold ${t.text}`}>Github Activity</h2>
        </div>
        <a
          href={PROFILE.github}
          target="_blank"
          rel="noreferrer"
          className={`inline-flex items-center gap-1.5 font-mono text-sm ${t.textMuted} hover:text-teal-400 transition-colors`}
        >
          @{PROFILE.githubUsername} <ExternalLink size={14} />
        </a>
      </div>

      <Reveal>
        {status === "loading" && (
          <p className={`font-mono text-sm ${t.textFaint} text-center`}>Loading contribution activity…</p>
        )}

        {status === "error" && (
          <p className={`font-mono text-sm ${t.textFaint} text-center`}>
            Couldn't load live contribution data right now — view the graph directly on{" "}
            <a href={PROFILE.github} target="_blank" rel="noreferrer" className="text-teal-400 hover:underline">
              GitHub
            </a>.
          </p>
        )}

        {status === "ready" && (
          <>
            <svg
              viewBox={`0 0 ${width} ${height}`}
              style={{ color: dotColor, maxWidth: `${width}px`, width: "100%", height: "auto" }}
              className="block mx-auto"
            >
              {weeks.map((week, wi) =>
                week.map((day, di) => {
                  if (!day) return null;
                  const r = DOT_RADIUS_BY_LEVEL[day.level] ?? DOT_RADIUS_BY_LEVEL[0];
                  return (
                    <circle
                      key={`${wi}-${di}`}
                      cx={wi * cellSize + cellSize / 2}
                      cy={di * cellSize + cellSize / 2}
                      r={r}
                      fill="currentColor"
                      opacity={day.level === 0 ? 0.35 : 1}
                    >
                      <title>{`${day.count} contributions on ${day.date}`}</title>
                    </circle>
                  );
                })
              )}
            </svg>
            <p className={`font-mono text-xs ${t.textFaint} mt-4 text-center`}>
              {total.toLocaleString()} contributions in the last year
            </p>
          </>
        )}
      </Reveal>
    </section>
  );
}

